// Validation & Generation
let totalCount = 0;
const allKeywords = new Set();
const rows = ["keyword,cluster,search_intent,target_page,location,priority,evidence_status,recommended_content"];

clusters.forEach(c => {
  if (c.keywords.length !== c.count) {
    throw new Error(`Cluster ${c.cluster} expected ${c.count} but got ${c.keywords.length}`);
  }
  c.keywords.forEach(k => {
    if (allKeywords.has(k.kw.toLowerCase())) {
      throw new Error(`Duplicate keyword detected: ${k.kw}`);
    }
    allKeywords.add(k.kw.toLowerCase());
    totalCount++;
    // Escape CSV values
    const escapeCsv = (val) => {
      if (typeof val === 'string' && (val.includes(',') || val.includes('"') || val.includes('\n'))) {
        return `"${val.replace(/"/g, '""')}"`;
      }
      return val;
    };
    rows.push([
      escapeCsv(k.kw),
      escapeCsv(c.cluster),
      escapeCsv(k.intent),
      escapeCsv(k.target),
      escapeCsv(k.loc),
      escapeCsv(k.prio),
      escapeCsv(k.ev),
      escapeCsv(k.rec),
    ].join(','));
  });
});

console.log(`Verified ${totalCount} distinct keywords across ${clusters.length} clusters.`);
if (totalCount !== 350) {
  throw new Error(`Total keyword count must be exactly 350, got ${totalCount}`);
}

const seoDir = path.join(__dirname, '..', 'seo');
if (!fs.existsSync(seoDir)) {
  fs.mkdirSync(seoDir, { recursive: true });
}

const outputPath = path.join(seoDir, 'keyword-map.csv');
fs.writeFileSync(outputPath, rows.join('\n'), 'utf8');
console.log(`Successfully generated ${outputPath} with exactly 350 keywords!`);
